package com.example.budgetpro.dao;

import com.example.budgetpro.models.Depense;
import com.example.budgetpro.services.Database;
import java.sql.*;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public class DepenseDAO {

    public static List<Depense> getAllDepenses() {
        List<Depense> depenses = new ArrayList<>();
        String query = "SELECT id_depense, montant, description, date, " +
                      "id_sous_categorie, id_utilisateur " +
                      "FROM depense ORDER BY date DESC";

        try {
            Connection conn = Database.getConnection();
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            while (rs.next()) {
                Depense depense = new Depense();
                depense.setIdDepense(rs.getInt("id_depense"));
                depense.setMontant(rs.getInt("montant"));
                depense.setDescription(rs.getString("description"));
                depense.setDate(rs.getDate("date").toLocalDate());
                depense.setSousCategorieId(rs.getInt("id_sous_categorie"));
                depense.setUserId(rs.getInt("id_utilisateur"));

                depenses.add(depense);
            }

            System.out.println(depenses.size() + " dépenses récupérées");

        } catch (SQLException e) {
            System.err.println("Erreur lors de la récupération des dépenses");
            e.printStackTrace();
        }

        return depenses;
    }

    /**
     * Récupérer les dépenses d'un utilisateur spécifique
     * @return 
     */
    public static List<Depense> getDepensesByUserId(int userId) {
        List<Depense> depenses = new ArrayList<>();
        String query = "SELECT id_depense, montant, description, date, " +
                      "id_sous_categorie, id_utilisateur " +
                      "FROM depense WHERE id_utilisateur = ? ORDER BY date DESC";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement pstmt = conn.prepareStatement(query);

            pstmt.setInt(1, userId);
            ResultSet rs = pstmt.executeQuery();

            while (rs.next()) {
                Depense depense = new Depense();
                depense.setIdDepense(rs.getInt("id_depense"));
                depense.setMontant(rs.getInt("montant"));
                depense.setDescription(rs.getString("description"));
                depense.setDate(rs.getDate("date").toLocalDate());
                depense.setSousCategorieId(rs.getInt("id_sous_categorie"));
                depense.setUserId(rs.getInt("id_utilisateur"));

                depenses.add(depense);
            }

        } catch (SQLException e) {
            System.err.println("Erreur lors de la récupération des dépenses par utilisateur");
            e.printStackTrace();
        }

        return depenses;
    }

    /**
     * Filtrer les dépenses par catégorie (via sous_categorie)
     * @return 
     */
    public List<Depense> getDepensesByCategorie(int categorieId) {
        List<Depense> depenses = new ArrayList<>();
        String query = "SELECT d.id_depense, d.montant, d.description, d.date, " +
                      "d.id_sous_categorie, d.id_utilisateur " +
                      "FROM depense d " +
                      "JOIN sous_categorie sc ON d.id_sous_categorie = sc.id_sous_categorie " +
                      "WHERE sc.id_categorie = ? " +
                      "ORDER BY d.date DESC";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement pstmt = conn.prepareStatement(query);

            pstmt.setInt(1, categorieId);
            ResultSet rs = pstmt.executeQuery();

            while (rs.next()) {
                Depense depense = new Depense();
                depense.setIdDepense(rs.getInt("id_depense"));
                depense.setMontant(rs.getInt("montant"));
                depense.setDescription(rs.getString("description"));
                depense.setDate(rs.getDate("date").toLocalDate());
                depense.setSousCategorieId(rs.getInt("id_sous_categorie"));
                depense.setUserId(rs.getInt("id_utilisateur"));

                depenses.add(depense);
            }

        } catch (SQLException e) {
            System.err.println("Erreur lors du filtrage par catégorie");
            e.printStackTrace();
        }

        return depenses;
    }

    /**
     * Filtrer les dépenses par période
     * @return 
     */
    public List<Depense> getDepensesByPeriode(LocalDate dateDebut, LocalDate dateFin) {
        List<Depense> depenses = new ArrayList<>();
        String query = "SELECT id_depense, montant, description, date, " +
                      "id_sous_categorie, id_utilisateur " +
                      "FROM depense " +
                      "WHERE date BETWEEN ? AND ? " +
                      "ORDER BY date DESC";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement pstmt = conn.prepareStatement(query);

            pstmt.setDate(1, Date.valueOf(dateDebut));
            pstmt.setDate(2, Date.valueOf(dateFin));
            ResultSet rs = pstmt.executeQuery();

            while (rs.next()) {
                Depense depense = new Depense();
                depense.setIdDepense(rs.getInt("id_depense"));
                depense.setMontant(rs.getInt("montant"));
                depense.setDescription(rs.getString("description"));
                depense.setDate(rs.getDate("date").toLocalDate());
                depense.setSousCategorieId(rs.getInt("id_sous_categorie"));
                depense.setUserId(rs.getInt("id_utilisateur"));

                depenses.add(depense);
            }

        } catch (SQLException e) {
            System.err.println("Erreur lors du filtrage par période");
            e.printStackTrace();
        }

        return depenses;
    }

    /**
     * Récupérer le nom de la catégorie d'une dépense
     * @return 
     */
    public String getCategorieNameByDepense(int idDepense) {
        String query = "SELECT c.nom_categorie " +
                      "FROM depense d " +
                      "JOIN sous_categorie sc ON d.id_sous_categorie = sc.id_sous_categorie " +
                      "JOIN categorie c ON sc.id_categorie = c.id_categorie " +
                      "WHERE d.id_depense = ?";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement pstmt = conn.prepareStatement(query);
            pstmt.setInt(1, idDepense);
            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                return rs.getString("nom_categorie");
            }

        } catch (SQLException e) {
            System.err.println("Erreur lors de la récupération du nom de catégorie");
            e.printStackTrace();
        }

        return "Inconnu";
    }
}

package com.example.budgetpro.dao;

import com.example.budgetpro.services.Database;
import java.sql.*;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * DAO pour les statistiques d'un utilisateur spécifique
 */
public class StatistiqueDAO {

    /**
     * Total des dépenses par catégorie pour un utilisateur
     * @return 
     */
    public Map<String, Double> getDepensesParCategorie(int userId) {
        Map<String, Double> data = new LinkedHashMap<>();

        String query = "SELECT c.nom_categorie, SUM(d.montant) as total " +
                "FROM depense d " +
                "JOIN sous_categorie sc ON d.id_sous_categorie = sc.id_sous_categorie " +
                "JOIN categorie c ON sc.id_categorie = c.id_categorie " +
                "WHERE d.id_utilisateur = ? " +  // ✅ AJOUT DU FILTRE
                "GROUP BY c.nom_categorie " +
                "ORDER BY total DESC";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, userId);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                data.put(rs.getString("nom_categorie"), rs.getDouble("total"));
            }

            System.out.println("✅ Dépenses par catégorie récupérées pour userId " + userId);

        } catch (SQLException e) {
            System.err.println("❌ Erreur dépenses par catégorie");
            e.printStackTrace();
        }

        return data;
    }

    /**
     * Total des dépenses par jour de la semaine pour un utilisateur
     */
    public Map<String, Double> getDepensesParJour(int userId) {
        Map<String, Double> data = new LinkedHashMap<>();

        // Initialiser les jours dans l'ordre 
        data.put("Lun", 0.0);
        data.put("Mar", 0.0);
        data.put("Mer", 0.0);
        data.put("Jeu", 0.0);
        data.put("Ven", 0.0);
        data.put("Sam", 0.0);
        data.put("Dim", 0.0);

        String query = "SELECT DAYOFWEEK(date) as jour, SUM(montant) as total " +
                "FROM depense " +
                "WHERE id_utilisateur = ? " +  // ✅ AJOUT DU FILTRE
                "GROUP BY DAYOFWEEK(date) " +
                "ORDER BY jour";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, userId);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                int jour = rs.getInt("jour");
                double total = rs.getDouble("total");

                // MySQL : 1=Dimanche, 2=Lundi, ..., 7=Samedi
                switch (jour) {
                    case 1 -> data.put("Dim", total);
                    case 2 -> data.put("Lun", total);
                    case 3 -> data.put("Mar", total);
                    case 4 -> data.put("Mer", total);
                    case 5 -> data.put("Jeu", total);
                    case 6 -> data.put("Ven", total);
                    case 7 -> data.put("Sam", total);
                }
            }

            System.out.println("✅ Dépenses par jour récupérées pour userId " + userId);

        } catch (SQLException e) {
            System.err.println("❌ Erreur dépenses par jour");
            e.printStackTrace();
        }

        return data;
    }

    /**
     * Tendance mensuelle des dépenses pour un utilisateur
     */
    public Map<String, Double> getDepensesParMois(int userId) {
        Map<String, Double> data = new LinkedHashMap<>();

        // Initialiser les mois
        String[] mois = {"Jan", "Fév", "Mar", "Avr", "Mai", "Jun",
                "Jul", "Aoû", "Sept", "Oct", "Nov", "Déc"};
        for (String m : mois) {
            data.put(m, 0.0);
        }

        String query = "SELECT MONTH(date) as mois, SUM(montant) as total " +
                "FROM depense " +
                "WHERE id_utilisateur = ? " +  // ✅ AJOUT DU FILTRE
                "AND YEAR(date) = YEAR(CURDATE()) " +
                "GROUP BY MONTH(date) " +
                "ORDER BY mois";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, userId);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                int moisNum = rs.getInt("mois");
                double total = rs.getDouble("total");
                data.put(mois[moisNum - 1], total);
            }

            System.out.println("✅ Dépenses par mois récupérées pour userId " + userId);

        } catch (SQLException e) {
            System.err.println("❌ Erreur dépenses par mois");
            e.printStackTrace();
        }

        return data;
    }

    /**
     * Tendance mensuelle des revenus pour un utilisateur
     */
    public Map<String, Double> getRevenusParMois(int userId) {
        Map<String, Double> data = new LinkedHashMap<>();

        // Initialiser les mois
        String[] mois = {"Jan", "Fév", "Mar", "Avr", "Mai", "Jun",
                "Jul", "Aoû", "Sep", "Oct", "Nov", "Déc"};
        for (String m : mois) {
            data.put(m, 0.0);
        }

        String query = "SELECT MONTH(date) as mois, SUM(montant) as total " +
                "FROM revenu " +
                "WHERE id_utilisateur = ? " +  // ✅ AJOUT DU FILTRE
                "AND YEAR(date) = YEAR(CURDATE()) " +
                "GROUP BY MONTH(date) " +
                "ORDER BY mois";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, userId);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                int moisNum = rs.getInt("mois");
                double total = rs.getDouble("total");
                data.put(mois[moisNum - 1], total);
            }

            System.out.println("✅ Revenus par mois récupérés pour userId " + userId);

        } catch (SQLException e) {
            System.err.println("❌ Erreur revenus par mois");
            e.printStackTrace();
        }

        return data;
    }

    /**
     * 🆕 BONUS : Total des dépenses pour un utilisateur
     */
    public double getTotalDepenses(int userId) {
        String query = "SELECT COALESCE(SUM(montant), 0) as total FROM depense WHERE id_utilisateur = ?";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, userId);
            ResultSet rs = stmt.executeQuery();

            if (rs.next()) {
                return rs.getDouble("total");
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }

        return 0.0;
    }

    /**
     * 🆕 BONUS : Total des revenus pour un utilisateur
     */
    public double getTotalRevenus(int userId) {
        String query = "SELECT COALESCE(SUM(montant), 0) as total FROM revenu WHERE id_utilisateur = ?";

        try {
            Connection conn = Database.getConnection();
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, userId);
            ResultSet rs = stmt.executeQuery();

            if (rs.next()) {
                return rs.getDouble("total");
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }

        return 0.0;
    }

    /**
     * 🆕 BONUS : Solde actuel (revenus - dépenses)
     */
    public double getSolde(int userId) {
        return getTotalRevenus(userId) - getTotalDepenses(userId);
    }
}

