import javafx.scene.control.Alert;

import java.time.YearMonth;
import java.util.regex.Pattern;

public class AuthServices {

    private static User currentUser = null;

    public static boolean login(String email, String password) {
        // Validation des entrées
        if (email == null || email.trim().isEmpty()) {
            System.out.println("Email vide");
            return false;
        }

        if (password == null || password.isEmpty()) {
            System.out.println("Mot de passe vide");
            return false;
        }

        // Nettoyer l'email
        email = email.trim().toLowerCase();

        try {
            Connection conn = Database.getConnection();
            String sql = "SELECT * FROM utilisateur WHERE email = ? AND password = ?";
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setString(1, email);
            stmt.setString(2, password);

            ResultSet rs = stmt.executeQuery();

            if (rs.next()) {
                // ✅ Identifiants corrects : créer la session
                currentUser = new User();
                currentUser.setId(rs.getInt("id_utilisateur"));
                currentUser.setNom(rs.getString("nom"));
                currentUser.setPrenom(rs.getString("prenom"));
                currentUser.setEmail(rs.getString("email"));
                currentUser.setTelephone(rs.getString("telephone"));
                currentUser.setPassword(rs.getString("password"));
                currentUser.setAge(rs.getInt("age"));
                currentUser.setSexe(rs.getString("sexe"));

                System.out.println("✅ Connexion réussie : " + currentUser.getPrenom());
                return true;
            } else {
                System.out.println(" Email ou mot de passe incorrect");
                return false;
            }

        } catch (SQLException e) {
            System.err.println("Erreur lors de la connexion : " + e.getMessage());
            return false;
        }
    }

    public static boolean register(String nom, String prenom, String email,
                                   String password, String telephone,
                                   String sexe, Integer age, Double soldeInitial) {
        // ========== VALIDATIONS ==========

        if (nom == null || nom.trim().isEmpty()) {
            System.out.println("Nom vide");
            return false;
        }

        if (prenom == null || prenom.trim().isEmpty()) {
            System.out.println(" Prénom vide");
            return false;
        }

        if (email == null || email.trim().isEmpty()) {
            System.out.println(" Email vide");
            return false;
        }

        if (password == null || password.isEmpty()) {
            System.out.println(" Mot de passe vide");
            return false;
        }

        if (telephone == null || telephone.trim().isEmpty()) {
            System.out.println(" Téléphone vide");
            return false;
        }

        if (sexe == null || sexe.isEmpty()) {
            System.out.println(" Sexe non renseigné");
            return false;
        }

        if (age == null) {
            System.out.println(" Âge non renseigné");
            return false;
        }

        if (soldeInitial == null) {
            soldeInitial = 0.0;
        }

        // Validations métier
        if (nom.trim().length() < 2) {
            System.out.println("❌ Nom trop court (min 2 caractères)");
            return false;
        }

        if (prenom.trim().length() < 2) {
            System.out.println("❌ Prénom trop court (min 2 caractères)");
            return false;
        }

       /* if (!isValidEmail(email)) {
            System.out.println("❌ Format d'email invalide");
            return false;
        }*/

        if (password.length() < 6) {
            System.out.println("❌ Mot de passe trop court (min 6 caractères)");
            Register.showAlert("Erreur ","Le  mot de passe doit avoir plus de six caractéres ", Alert.AlertType.INFORMATION);
            return false;
        }

        /*if (!isValidPhone(telephone)) {
            System.out.println("❌ Format de téléphone invalide");
            return false;
        }*/

        if (age < 13 || age > 120) {
            System.out.println("Âge invalide (doit être entre 13 et 120)");
            return false;
        }

        if (!sexe.equals("Homme") && !sexe.equals("Femme") && !sexe.equals("Autre")) {
            System.out.println(" Sexe invalide");
            return false;
        }

        if (soldeInitial < 0) {
            System.out.println("Solde initial ne peut pas être négatif");
            return false;
        }

        // Nettoyer les données
        nom = nom.trim();
        prenom = prenom.trim();
        email = email.trim().toLowerCase();
        telephone = telephone.trim();

        Connection conn = null;

        try {
            conn = Database.getConnection();
            conn.setAutoCommit(false); // ← IMPORTANT : Transaction

            // ========== Vérifier si l'email existe déjà ==========
            String checkSql = "SELECT id_utilisateur FROM utilisateur WHERE email = ?";
            PreparedStatement checkStmt = conn.prepareStatement(checkSql);
            checkStmt.setString(1, email);
            ResultSet rs = checkStmt.executeQuery();

            if (rs.next()) {
                System.out.println("❌ Cet email est déjà utilisé");
                conn.rollback(); // Annuler la transaction
                return false;
            }

            // ========== Vérifier si le téléphone existe déjà ==========
            String checkPhoneSql = "SELECT id_utilisateur FROM utilisateur WHERE telephone = ?";
            PreparedStatement checkPhoneStmt = conn.prepareStatement(checkPhoneSql);
            checkPhoneStmt.setString(1, telephone);
            ResultSet rsPhone = checkPhoneStmt.executeQuery();

            if (rsPhone.next()) {
                System.out.println("❌ Ce numéro de téléphone est déjà utilisé");
                conn.rollback(); // Annuler la transaction
                return false;
            }

            // ========== Insérer l'utilisateur ==========
            String insertUserSql = """
            INSERT INTO utilisateur (nom, prenom, email, password, telephone, sexe, age) 
            VALUES (?, ?, ?, ?, ?, ?, ?)
        """;

            PreparedStatement insertUserStmt = conn.prepareStatement(insertUserSql, Statement.RETURN_GENERATED_KEYS);
            insertUserStmt.setString(1, nom);
            insertUserStmt.setString(2, prenom);
            insertUserStmt.setString(3, email);
            insertUserStmt.setString(4, password); // ⚠️ En production : hasher avec BCrypt !
            insertUserStmt.setString(5, telephone);
            insertUserStmt.setString(6, sexe);
            insertUserStmt.setInt(7, age);

            int rowsAffected = insertUserStmt.executeUpdate();

            if (rowsAffected == 0) {
                System.out.println("❌ Erreur lors de l'inscription");
                conn.rollback(); // Annuler la transaction
                return false;
            }

            // ========== Récupérer l'ID de l'utilisateur créé ==========
            ResultSet generatedKeys = insertUserStmt.getGeneratedKeys();
            int userId = 0;

            if (generatedKeys.next()) {
                userId = generatedKeys.getInt(1);
            } else {
                System.out.println("❌ Impossible de récupérer l'ID utilisateur");
                conn.rollback(); // Annuler la transaction
                return false;
            }

            // ========== Insérer le solde initial dans la table budgets ==========
            if (soldeInitial > 0) {
                String insertBudgetSql = """
                INSERT INTO budget (montant, id_utilisateur, id_categorie) 
                VALUES (?, ?, NULL)
            """;

                PreparedStatement insertBudgetStmt = conn.prepareStatement(insertBudgetSql);
                insertBudgetStmt.setDouble(1, soldeInitial);
                insertBudgetStmt.setInt(2, userId);

                int budgetRows = insertBudgetStmt.executeUpdate();

                if (budgetRows > 0) {
                    System.out.println("✅ Solde initial enregistré : " + soldeInitial + "€");
                } else {
                    System.out.println("⚠️ Erreur lors de l'enregistrement du solde initial");
                    conn.rollback(); // Annuler TOUTE la transaction (user + budget)
                    return false;
                }
            }

            // ========== VALIDER LA TRANSACTION ==========
            conn.commit(); //
            CategorieService.initCategoriesDefaut(userId);
            BudgetService.initBudgetsMois(userId, YearMonth.now());
            // ← IMPORTANT : Valider toutes les modifications

            // ========== Créer la session utilisateur ==========
            currentUser = new User(nom, prenom, email, password, telephone);
            currentUser.setId(userId);
            currentUser.setSexe(sexe);
            currentUser.setAge(age);
            currentUser.setSoldeInitial(soldeInitial);
            currentUser.setCreatedAt(LocalDateTime.now());

            System.out.println("✅ Inscription réussie : " + currentUser.getFullName());
            System.out.println("   - Sexe: " + sexe);
            System.out.println("   - Âge: " + age);
            System.out.println("   - Solde initial: " + soldeInitial + "€");

            return true;

        } catch (SQLException e) {
            System.err.println("❌ Erreur SQL lors de l'inscription : " + e.getMessage());
            e.printStackTrace();

            // En cas d'erreur, annuler toute la transaction
            try {
                if (conn != null) {
                    conn.rollback();
                    System.out.println("⚠️ Transaction annulée");
                }
            } catch (SQLException rollbackEx) {
                System.err.println("❌ Erreur lors du rollback : " + rollbackEx.getMessage());
            }

            return false;

        } finally {
            // Remettre l'auto-commit à true
            try {
                if (conn != null) {
                    conn.setAutoCommit(true);
                }
            } catch (SQLException e) {
                System.err.println("❌ Erreur lors de la réactivation de l'auto-commit : " + e.getMessage());
            }
        }
    }


    public static boolean resetPassword(String email, String newPassword) {
        if (email == null || email.trim().isEmpty()) return false;
        if (newPassword == null || newPassword.length() < 6) return false;

        email = email.trim().toLowerCase();

        try {
            Connection conn = Database.getConnection();

            // Vérifier que l'email existe
            String checkSql = "SELECT id_utilisateur FROM utilisateur WHERE email = ?";
            PreparedStatement checkStmt = conn.prepareStatement(checkSql);
            checkStmt.setString(1, email);
            ResultSet rs = checkStmt.executeQuery();

            if (!rs.next()) {
                System.out.println("❌ Aucun compte avec cet email : " + email);
                return false;
            }

            // Mettre à jour le mot de passe
            String updateSql = "UPDATE utilisateur SET password = ? WHERE email = ?";
            PreparedStatement updateStmt = conn.prepareStatement(updateSql);
            updateStmt.setString(1, newPassword); // ⚠️ En production : hasher avec BCrypt !
            updateStmt.setString(2, email);

            int rows = updateStmt.executeUpdate();

            if (rows > 0) {
                System.out.println("✅ Mot de passe réinitialisé pour : " + email);
                return true;
            } else {
                System.out.println("❌ Échec de la mise à jour");
                return false;
            }

        } catch (SQLException e) {
            System.err.println("❌ Erreur SQL resetPassword : " + e.getMessage());
            return false;
        }
    }
    public static User getCurrentUser() {
        return currentUser;
    }
    public static boolean isLoggedIn() {return currentUser != null;}
    public static void logout() {
        currentUser = null;
        System.out.println("Session fermée.");
    }


}

package com.example.budgetpro.services;

import com.example.budgetpro.models.Budget;
import java.sql.*;
import java.time.LocalDate;
import java.time.YearMonth;

public class BudgetService {

    /**
     * Initialise les budgets du mois pour toutes les catégories.
     * Initialise aussi le budgetTotal du mois (id_categorie IS NULL, mois = premier jour du mois)
     * en copiant le montant du budget de référence (id_categorie IS NULL, mois IS NULL).
     * INSERT IGNORE garantit qu'on ne retouche pas un mois déjà initialisé.
     */
    public static void initBudgetsMois(int userId, YearMonth mois) {
        try {
            Connection conn = Database.getConnection();
            LocalDate premierJourMois = mois.atDay(1);

            // 1. Initialiser le budgetTotal du mois si absent
            //    Pattern : id_categorie IS NULL + mois = premier jour du mois
            String initTotalSql = """
                INSERT IGNORE INTO budget (id_utilisateur, id_categorie, montant, mois)
                SELECT ?, NULL,
                    COALESCE((SELECT montant FROM budget b2
                               WHERE b2.id_utilisateur = ? AND b2.id_categorie IS NULL AND b2.mois IS NULL
                               LIMIT 1), 0),
                    ?
                FROM dual
                WHERE NOT EXISTS (
                    SELECT 1 FROM budget b3
                    WHERE b3.id_utilisateur = ? AND b3.id_categorie IS NULL AND b3.mois = ?
                )
            """;
            PreparedStatement initTotalStmt = conn.prepareStatement(initTotalSql);
            initTotalStmt.setInt(1, userId);
            initTotalStmt.setInt(2, userId);
            initTotalStmt.setDate(3, Date.valueOf(premierJourMois));
            initTotalStmt.setInt(4, userId);
            initTotalStmt.setDate(5, Date.valueOf(premierJourMois));
            initTotalStmt.executeUpdate();

            // 2. Initialiser les budgets de catégories à 0 pour ce mois
            String getCatSql = "SELECT id_categorie FROM categorie WHERE id_utilisateur = ?";
            PreparedStatement getCatStmt = conn.prepareStatement(getCatSql);
            getCatStmt.setInt(1, userId);
            ResultSet rs = getCatStmt.executeQuery();

            while (rs.next()) {
                int categorieId = rs.getInt("id_categorie");
                String insertSql = """
                    INSERT IGNORE INTO budget (montant, id_utilisateur, id_categorie, mois)
                    VALUES (0, ?, ?, ?)
                """;
                PreparedStatement insertStmt = conn.prepareStatement(insertSql);
                insertStmt.setInt(1, userId);
                insertStmt.setInt(2, categorieId);
                insertStmt.setDate(3, Date.valueOf(premierJourMois));
                insertStmt.executeUpdate();
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    /**
     * Récupère le budgetTotal du mois affiché.
     * Cherche la ligne : id_categorie IS NULL + mois = premier jour du mois.
     * Ce montant représente le budget de départ du mois, augmenté par les revenus ajoutés.
     */
    public static double getBudgetTotalMois(int userId, YearMonth mois) {
        try {
            Connection conn = Database.getConnection();
            LocalDate premierJour = mois.atDay(1);

            String sql = """
                SELECT montant FROM budget
                WHERE id_utilisateur = ? AND id_categorie IS NULL AND mois = ?
                LIMIT 1
            """;
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setInt(1, userId);
            stmt.setDate(2, Date.valueOf(premierJour));

            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                return rs.getDouble("montant");
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }
        return 0.0;
    }

    /**
     * Met à jour le budgetTotal du mois affiché uniquement.
     * N'affecte aucun autre mois ni le budget de référence (mois IS NULL).
     */
    public static boolean updateBudgetTotalMois(int userId, YearMonth mois, double nouveauMontant) {
        try {
            Connection conn = Database.getConnection();
            LocalDate premierJour = mois.atDay(1);

            String sql = """
                UPDATE budget SET montant = ?
                WHERE id_utilisateur = ? AND id_categorie IS NULL AND mois = ?
            """;
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setDouble(1, nouveauMontant);
            stmt.setInt(2, userId);
            stmt.setDate(3, Date.valueOf(premierJour));

            return stmt.executeUpdate() > 0;

        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    /**
     * Ajoute un montant au budgetTotal du mois (appelé lors de l'ajout d'un revenu).
     * N'affecte que le mois de la date du revenu.
     */
    public static boolean ajouterAuBudgetTotalMois(int userId, YearMonth mois, double montantRevenu) {
        try {
            Connection conn = Database.getConnection();
            LocalDate premierJour = mois.atDay(1);

            // S'assurer que la ligne du mois existe avant d'incrémenter
            initBudgetsMois(userId, mois);

            String sql = """
                UPDATE budget SET montant = montant + ?
                WHERE id_utilisateur = ? AND id_categorie IS NULL AND mois = ?
            """;
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setDouble(1, montantRevenu);
            stmt.setInt(2, userId);
            stmt.setDate(3, Date.valueOf(premierJour));

            return stmt.executeUpdate() > 0;

        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    /**
     * Récupère le budget initial de référence (entré à l'inscription, mois IS NULL).
     * Sert uniquement à initialiser les nouveaux mois.
     */
    public static double getBudgetInitial(int userId) {
        try {
            Connection conn = Database.getConnection();
            String sql = "SELECT montant FROM budget WHERE id_utilisateur = ? AND id_categorie IS NULL AND mois IS NULL";
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setInt(1, userId);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                return rs.getDouble("montant");
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return 0.0;
    }

    // ============================================================
    // Méthodes pour les budgets de catégories (inchangées)
    // ============================================================

    public static Budget getBudgetCategorieParMois(int userId, int categorieId, YearMonth mois) {
        try {
            Connection conn = Database.getConnection();
            LocalDate premierJour = mois.atDay(1);

            String sql = "SELECT * FROM budget WHERE id_utilisateur = ? AND id_categorie = ? AND mois = ?";
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setInt(1, userId);
            stmt.setInt(2, categorieId);
            stmt.setDate(3, Date.valueOf(premierJour));

            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                Budget budget = new Budget();
                budget.setIdBudget(rs.getInt("id_budget"));
                budget.setMontant(rs.getDouble("montant"));
                budget.setUserId(rs.getInt("id_utilisateur"));
                budget.setCategorieId(rs.getInt("id_categorie"));
                budget.setMois(rs.getDate("mois").toLocalDate());
                return budget;
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }
        return null;
    }

    public static boolean updateBudget(int budgetId, double nouveauMontant) {
        try {
            Connection conn = Database.getConnection();
            String sql = "UPDATE budget SET montant = ? WHERE id_budget = ?";
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setDouble(1, nouveauMontant);
            stmt.setInt(2, budgetId);
            return stmt.executeUpdate() > 0;
        } catch (SQLException e) {
            e.printStackTrace();
            return false;
        }
    }

    public static double getTotalBudgetsCategoriesMois(int userId, YearMonth mois) {
        try {
            Connection conn = Database.getConnection();
            LocalDate premierJour = mois.atDay(1);

            // Exclure la ligne budgetTotal du mois (id_categorie IS NULL) - on veut seulement les catégories
            String sql = """
                SELECT COALESCE(SUM(montant), 0) as total FROM budget
                WHERE id_utilisateur = ? AND mois = ? AND id_categorie IS NOT NULL
            """;
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setInt(1, userId);
            stmt.setDate(2, Date.valueOf(premierJour));

            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                return rs.getDouble("total");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return 0.0;
    }

    /**
     * Mise à jour du budget de référence (mois IS NULL).
     * N'affecte pas les mois déjà initialisés.
     */
    public static boolean updateBudgetInitial(int userId, double nouveauMontant) {
        try {
            Connection conn = Database.getConnection();
            String sql = "UPDATE budget SET montant = ? WHERE id_utilisateur = ? AND id_categorie IS NULL AND mois IS NULL";
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setDouble(1, nouveauMontant);
            stmt.setInt(2, userId);
            return stmt.executeUpdate() > 0;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }
}

package com.example.budgetpro.services;

import com.example.budgetpro.models.Categorie;
