}

/* ---- Conteneur principal du chart ---- */
.chart {
    -fx-background-color: transparent;
    -fx-padding: 5;
}

.chart-content {
    -fx-background-color: transparent;
}

.chart-plot-background {
    -fx-background-color: #1e2738;
}

/* ---- Titre du chart ---- */
.chart-title {
    -fx-text-fill: #e2e8f0;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
}

/* ---- Axes ---- */
.axis {
    -fx-tick-label-fill: #a0aec0;
    -fx-minor-tick-visible: false;
}

.axis-label {
    -fx-text-fill: #a0aec0;
    -fx-font-size: 12px;
}

.axis:top .axis-minor-tick-mark,
.axis:bottom .axis-minor-tick-mark,
.axis:left .axis-minor-tick-mark,
.axis:right .axis-minor-tick-mark {
    -fx-stroke: transparent;
}

.axis:top .axis-tick-mark,
.axis:bottom .axis-tick-mark,
.axis:left .axis-tick-mark,
.axis:right .axis-tick-mark {
    -fx-stroke: #4a5568;
}

/* ---- Lignes de grille ---- */
.chart-horizontal-grid-lines {
    -fx-stroke: #3a4660;
    -fx-stroke-width: 1;
}

.chart-vertical-grid-lines {
    -fx-stroke: #3a4660;
    -fx-stroke-width: 1;
}

.chart-horizontal-zero-line {
    -fx-stroke: #718096;
}

.chart-vertical-zero-line {
    -fx-stroke: #718096;
}

/* ---- Légende ---- */
.chart-legend {
    -fx-background-color: transparent;
}

.chart-legend-item {
    -fx-text-fill: #cbd5e0;
    -fx-font-size: 12px;
}

/* ---- PieChart — labels des portions ---- */
.chart-pie-label {
    -fx-fill: #e2e8f0;
    -fx-font-size: 12px;
}

.chart-pie-label-line {
    -fx-stroke: #a0aec0;
}

/* ---- LineChart — ligne ---- */
.chart-series-line {
    -fx-stroke-width: 2.5;
}

.chart-line-symbol {
    -fx-background-radius: 5px;
    -fx-padding: 4px;
}

/* ---- BarChart — barres ---- */
.chart-bar {
    -fx-bar-fill: #a78bfa;
    -fx-background-radius: 3 3 0 0;
}

/* ===== COMBOBOX ===== */
.combo-box {
    -fx-background-color: #2d3748;
    -fx-border-color: #4a5568;
    -fx-border-radius: 5;
}

